target.css:
:root {
  --ink: #27302f;
  --paper: #fffdf7;
  --line: #d7d1c4;
  --sage: #dce8d8;
  --sage-dark: #426a59;
}

.pickup-token {
  width: 450px;
  box-sizing: border-box;
  overflow: hidden;
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 16px;
}

.token-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  background: var(--sage);
  border-bottom: 2px solid var(--ink);
}

.scissors {
  font-size: 25px;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--sage-dark);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.2px;
}

h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1.1;
}

.ticket-no {
  margin-left: auto;
  padding: 5px 8px;
  border: 1px solid var(--sage-dark);
  border-radius: 6px;
  color: var(--sage-dark);
  font-size: 13px;
}

.garment-details {
  padding: 12px 16px;
}

.garment-details p {
  margin: 5px 0;
  font-size: 14px;
}

.garment-details span {
  display: inline-block;
  width: 48px;
  color: var(--sage-dark);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.7px;
}

.token-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 1px dashed var(--line);
  font-size: 13px;
}

button {
  padding: 7px 11px;
  border: 0;
  border-radius: 7px;
  background: var(--ink);
  color: var(--paper);
  font-size: 13px;
  font-weight: 700;
}
